mapper.select:
SELECT 
FROM history_record
WHERE device_id = #{deviceId}
  AND timestamp >= #{startTime}
  AND timestamp <= #{endTime}
ORDER BY timestamp DESC

SELECT h.id, h.device_id, h.topic, h.payload, h.timestamp, h.created_at,
       d.device_name AS device_name
FROM history_record h
LEFT JOIN device d ON h.device_id = d.id AND d.deleted = 0
WHERE 1=1

    AND h.device_id = #{dto.deviceId}


    AND h.topic LIKE CONCAT('%', #{dto.topic}, '%')


    AND h.timestamp >= #{dto.startTime}


    AND h.timestamp <= #{dto.endTime}


    AND d.owner_id = #{userId}

ORDER BY h.timestamp DESC
